            {% assign viewAllTranslated = "suggestion.viewAll" | translate: translations, "View all {{ count }} products" | replace: '{{ count }}', count -%}
            <div class="boost-sd__view-all" data-group="view-all-products" aria-label="Button: {{ viewAllTranslated }}" data-title="{{ query | escape }}">
              <a class="boost-sd__view-all-link" href="{{ current_locale }}/search?q={{ query | escape }}">
                <span class="boost-sd__view-all-text">
                  {{ viewAllTranslated }}
                  <svg class="boost-sd__view-all-icon" width="16" height="16" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path fill-rule="evenodd" clip-rule="evenodd" d="M14.1657 7.43443L10.1657 3.43443C9.8529 3.12163 9.3473 3.12163 9.0345 3.43443C8.7217 3.74723 8.7217 4.25283 9.0345 4.56563L11.6689 7.20003H2.4001C1.9577 7.20003 1.6001 7.55843 1.6001 8.00003C1.6001 8.44163 1.9577 8.80003 2.4001 8.80003H11.6689L9.0345 11.4344C8.7217 11.7472 8.7217 12.2528 9.0345 12.5656C9.1905 12.7216 9.3953 12.8 9.6001 12.8C9.8049 12.8 10.0097 12.7216 10.1657 12.5656L14.1657 8.56563C14.4785 8.25283 14.4785 7.74723 14.1657 7.43443" fill="#5C5F62"></path>
                  </svg>
                </span>
              </a>
            </div>
            {% endif %}
            {% endif %}
          </div>
          {% else %}
          {% assign autocomplete_classes = '' %}
          {% if suggestions.size == 0 and collections.size == 0 and pages.size == 0 -%}
          {% assign autocomplete_classes = autocomplete_classes | append : 'boost-sd__instant-search-no-other ' %}
          {% endif %}
          {% if products.size == 0 -%}
          {% assign autocomplete_classes1 = autocomplete_classes1 | append : 'boost-sd__instant-search-no-product ' %}
          {% endif %}
          <div class="boost-sd__instant-search-autocomplete {{ autocomplete_classes }} boost-sd__g-flexColumn">
            {% if suggestions.size > 0 or collections.size > 0 or pages.size > 0 or products.size > 0 or did_you_mean.size != 0 -%}
            <div class="boost-sd__instant-search-column boost-sd__instant-search-column--others boost-sd__g-scrollable">
              <!-- TEMPLATE DID YOU MEAN -->
              {% assign termList = '' %}
              {% if did_you_mean.size != 0 and all_empty == false %}
              <div class="boost-sd__spelling-correction" data-group="empty" data-aria-label="{{ query | escape }}" data-label="{{ query | escape }}">
                <p class="boost-sd__spelling-correction-desc boost-sd__spelling-correction-desc--list">
                  {% for term in did_you_mean %}
                  {% assign escapedTerm = term | escape %}
                  {% assign termList = termList | append: '<a tabindex="-1" class="boost-sd__spelling-correction-suggest-link" href="/search?q=[[term]]">[[term]]</a>' | replace: '[[term]]', escapedTerm %}
                  {% endfor %}
                  {% assign didYouMeanTranslated = "suggestion.didYouMean" | translate: translations, "Did you mean: {{ terms }}" | replace: '{{ terms }}', termList -%}
                  {{ didYouMeanTranslated }}
                </p>
              </div>
              {% endif %}
