                            <img id="product-image-{{ widgetDesignSettings.bundleImageData }}" class="boost-sd__product-image-img boost-sd__product-image-img--main boost-sd__product-image-img--fullheight" src="{{ product.images_info[0].src }}" alt="{{ product.title | escape }}" width="auto" height="auto" />
                            {% else %}
                            <img id="product-image-{{ widgetDesignSettings.bundleImageData }}" class="boost-sd__product-image-img boost-sd__product-image-img--fullheight" src="https://cdn.shopify.com/extensions/201f4d7b-8d39-43a4-82de-e6f412341695/0.0.0/assets/boost-pfs-no-image.jpg?v=1677838268" alt="No image" width="auto" height="auto" />
                            {% endif %}
                          </div>
                          {% endif %}
                          {% endfor %}
                        </div>
                        {% endif %}
