                        {% else %}
                        <img class="boost-sd__suggestion-queries-item-img" src="https://cdn.shopify.com/extensions/201f4d7b-8d39-43a4-82de-e6f412341695/0.0.0/assets/boost-pfs-no-image.jpg?v=1677838268" alt="{{ product.title | escape }}" width="auto" height="auto" />
